<?php $this->layout('default'); use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V; $rows = H::quickReplies(); $edit = null; foreach ($rows as $r) { if ((string) $r['id'] === V::queryString('editar')) { $edit = $r; } } ?>
<div class="cms-form-list"><form class="cms-card" method="post" action="/acao/quick-reply-save"><header class="cms-card-head"><div><h2><?= $edit ? 'Editar resposta' : 'Cadastrar resposta' ?></h2><small>Aparece ao responder um chamado.</small></div><?= V::icon('edit') ?></header><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?: '' ?>"><input type="hidden" name="back" value="/chamados/respostas"><?= V::field('Título', 'title', $edit['title'] ?? '', ['required' => true]) ?><?= V::field('Texto', 'body', $edit['body'] ?? '', ['type' => 'textarea', 'rows' => 6, 'required' => true]) ?><div class="cms-form-end"><button class="cms-btn-primary">Salvar resposta</button></div></form>
<section class="cms-card"><header class="cms-card-head"><div><h2>Respostas cadastradas</h2></div><b class="cms-count"><?= count($rows) ?></b></header><?php if ($rows === []): ?><?= V::empty('Nenhuma resposta rápida cadastrada.') ?><?php endif; foreach ($rows as $q): ?><div class="cms-row"><div><strong><?= V::e($q['title']) ?></strong><br><small><?= V::e(mb_strimwidth($q['body'], 0, 110, '…')) ?></small></div><div class="cms-td-actions"><?= V::iconLink('?editar=' . (int) $q['id'], 'Editar') ?><?= V::iconAction('quick-reply-delete', 'Excluir', ['id' => $q['id']], 'Excluir esta resposta?') ?></div></div><?php endforeach; ?></section></div>
